function doLogin(){const email=$('#email').value.trim().toLowerCase(),pw=$('#password').value;if(email==='docente@sql11.local'&&pw==='Docente123!'){if(!state.users.some(x=>x.email===email))state.users.push({email,first:'Docente',last:'Demo',role:'teacher'});state.current=email;save();return render()}if(email==='estudiante@sql11.local'&&pw==='Estudiante123!'){if(!state.users.some(x=>x.email===email))state.users.push({email,first:'Estudiante',last:'Demo',code:'EST-001',inst:'Institución Demo',group:'A',role:'student'});state.current=email;save();return render()}const u=state.users.find(x=>x.email===email&&x.password===pw);if(!u)return alert('Correo o contraseña incorrectos.');state.current=email;save();render()}
function doRegister(){const v=id=>$('#'+id).value.trim();let u={email:v('email').toLowerCase(),password:v('password'),first:v('first'),last:v('last'),code:v('code'),inst:v('inst'),group:v('group'),role:'student'};if(Object.values(u).some(x=>!x))return alert('Completa todos los campos.');if(u.password.length<8)return alert('La contraseña debe tener al menos 8 caracteres.');if(state.users.some(x=>x.email===u.email||x.code===u.code))return alert('Correo o código ya registrado.');state.users.push(u);state.current=u.email;save();render()}
function logout(){state.current=null;save();home()}
function prog(){const p=state.progress[state.current]||{};return lessons.reduce((n,_,i)=>n+(p[i+1]?.done?1:0),0)}
function dashboard(){const u=state.users.find(x=>x.email===state.current);if(!u)return home();if(u.role==='teacher')return teacher();const done=prog();const pct=done*5;let cards='';for(let i=0;i<20;i++){const id=i+1, prev=id===1||state.progress[state.current]?.[id-1]?.done, pr=state.progress[state.current]?.[id], unlocked=prev||pr?.done;cards+=`<article class="lesson ${!unlocked?'lock':''}"><div class="num">${String(id).padStart(2,'0')}</div><div><span class="tag">${lessons[i][2]} min · ${lessons[i][1]}</span><h3>${lessons[i][0]}</h3><p>${lessons[i][3]}</p></div>${pr?.done?'<span>✓ Completada</span>':unlocked?`<button class="btn small primary" onclick="startLesson(${id})">Continuar</button>`:'<span>🔒 Bloqueada</span>'}</article>`}shell(`<div class="head"><div><span class="eyebrow">MI RECORRIDO</span><h1>Hola, ${esc(u.first)} 👋</h1><p>${esc(u.inst||'')} · Grado 11 · Grupo ${esc(u.group||'')}</p></div><div class="ring" style="--deg:${pct*3.6}deg"><i>${pct}%</i></div></div><div class="bar"><span style="width:${pct}%"></span></div><h2>20 lecciones</h2><div class="grid">${cards}</div><div class="panel exam-panel" style="margin-top:18px"><span class="eyebrow">DESAFÍO FINAL</span><h2>Examen final</h2><p>Se desbloquea cuando completes las 20 lecciones. Tienes máximo 3 intentos y la nota final será la más alta.</p><button class="btn primary" onclick="examIntro()">Ver instrucciones del examen</button></div>`)}
function startLesson(id){
  const u=state.users.find(x=>x.email===state.current);
  if(id>1&&!state.progress[state.current]?.[id-1]?.done)return alert('Debes completar la lección anterior.');
  state.progress[state.current]??={};
  const existing=state.progress[state.current][id];
  if(existing?.done){ lessonView(id); return; }
  const proceed=confirm(`REGISTRO DE ACTIVIDAD\n\nEstudiante: ${u.first} ${u.last}\nCódigo: ${u.code||'—'}\nInstitución: ${u.inst||'—'}\nGrado: 11 · Grupo: ${u.group||'—'}\n\nAntes de iniciar, confirma que realizarás esta actividad de manera individual.\n\n¿Deseas comenzar la lección ${id}?`);
  if(!proceed)return;
  state.progress[state.current][id]??={started:new Date().toISOString(),done:false,answers:[]};
  state.progress[state.current][id].registration={name:`${u.first} ${u.last}`,code:u.code||'',institution:u.inst||'',group:u.group||'',accepted:true,date:new Date().toISOString()};
  if(!Array.isArray(state.progress[state.current][id].questionOrder)){
    state.progress[state.current][id].questionOrder=shuffleIndexes(lessons[id-1][5].length, `${state.current}|${id}`);
  }
  save(); lessonView(id);
}
function shuffleIndexes(length, seedText){
  const arr=Array.from({length},(_,i)=>i);
  let seed=0;
  for(let i=0;i<seedText.length;i++) seed=(seed*31+seedText.charCodeAt(i))>>>0;
  for(let i=arr.length-1;i>0;i--){
    seed=(1664525*seed+1013904223)>>>0;
    const j=seed%(i+1);
    [arr[i],arr[j]]=[arr[j],arr[i]];
  }
  return arr;
}
function lessonView(id){
  const l=lessons[id-1];
  const progress=state.progress[state.current][id]||{};
  const order=Array.isArray(progress.questionOrder)?progress.questionOrder:shuffleIndexes(l[5].length, `${state.current}|${id}`);
  if(!Array.isArray(progress.questionOrder)){
    progress.questionOrder=order;
    state.progress[state.current][id]=progress;
    save();
  }
  let html=`<div class="lessonview"><a href="#" onclick="dashboard();return false">← Mi progreso</a>
  <div class="intro"><span class="eyebrow">LECCIÓN ${String(id).padStart(2,'0')} · ${l[1]}</span><h1>${l[0]}</h1><p class="lead">${l[3]}</p></div>
  <div class="info"><h3>Concepto clave</h3><p>${l[4]}</p></div>
  <div class="example"><b>Ejemplo</b><pre>SELECT nombre, grupo FROM estudiantes WHERE grupo = '11-1';</pre></div>
  <div class="activity"><b>RETO INTERACTIVO · 4 PREGUNTAS</b><p>Las preguntas aparecen en un orden personalizado para cada estudiante.</p>`;
  order.forEach((qIndex,displayIndex)=>{
    const q=l[5][qIndex];
    html+=`<section class="question-block" data-q="${displayIndex}" data-original="${qIndex}">
      <h2>${displayIndex+1}. ${esc(q[0])}</h2>
      <div class="opts">${q[1].map((o,i)=>`<button type="button" class="opt" data-i="${i}">${'ABCD'[i]}. ${esc(o)}</button>`).join('')}</div>
      <button type="button" class="btn primary check-lesson" data-q="${displayIndex}">Revisar respuesta</button>
      <div class="fb" id="fb-${displayIndex}"></div>
    </section>`;
  });
  html+=`</div><div class="panel"><h3>Resumen</h3><p>Revisa las cuatro preguntas, lee la retroalimentación y luego finaliza la lección.</p><button class="btn primary" onclick="completeLesson(${id})">✓ Finalizar lección ${id}</button></div></div>`;
  shell(html);
  document.querySelectorAll('.question-block').forEach(block=>{
    let selected=null;
    block.querySelectorAll('.opt').forEach(b=>b.onclick=()=>{
      block.querySelectorAll('.opt').forEach(x=>x.classList.remove('sel'));
      b.classList.add('sel');
      selected=+b.dataset.i;
    });
    block.querySelector('.check-lesson').onclick=()=>{
      if(selected===null)return alert('Selecciona una opción.');
      const qIndex=+block.dataset.original, q=l[5][qIndex], ok=selected===q[2];
      block.querySelector('.fb').innerHTML=`<div class="feedback ${ok?'ok':'bad'}"><b>${ok?'¡Correcto!':'Revisa tu respuesta.'}</b><br>${esc(q[3])}</div>`;
      state.progress[state.current][id].answers??=[];
      state.progress[state.current][id].answers.push({question:qIndex,selected,correct:ok,time:new Date().toISOString()});
      save();
    };
  });
}
function completeLesson(id){state.progress[state.current][id].done=true;state.progress[state.current][id].completed=new Date().toISOString();save();alert('Lección completada. La siguiente lección ha sido desbloqueada.');dashboard()}
function examIntro(){if(prog()<20)return alert('Completa las 20 lecciones para desbloquear el examen.');const attempts=state.attempts[state.current]||[];shell(`<div class="form"><span class="eyebrow">EVALUACIÓN FINAL</span><h1>Examen de bases de datos y SQL</h1><p class="lead">20 preguntas tipo ICFES/Saber, con 4 opciones y una sola respuesta correcta.</p><div class="stats"><article><b>20</b>preguntas</article><article><b>4</b>opciones</article><article><b>3</b>intentos</article><article><b>1.0–5.0</b>escala</article></div><div class="notice"><b>Calificación:</b> nota = 1.0 + (aciertos / 20) × 4.0, redondeada a una cifra decimal. 0 aciertos = 1.0 y 20 aciertos = 5.0. La nota final será la más alta obtenida en los tres intentos.</div><p>Intentos usados: <b>${attempts.length}/3</b></p>${attempts.length<3?`<button class="btn primary" onclick="startExam()">Comenzar intento ${attempts.length+1}</button>`:`<button class="btn secondary" onclick="examResults()">Ver resultados</button>`}</div>`)}
function startExam(){state.exam={i:0,answers:[]};save();examQuestion()}
function examQuestion(){const e=state.exam,q=exam[e.i];shell(`<div class="examq"><span class="eyebrow">PREGUNTA ${e.i+1} DE 20</span><div class="bar"><span style="width:${((e.i+1)/20)*100}%"></span></div><h1>${q[0]}</h1><div class="opts">${q[1].map((o,i)=>`<button class="opt" data-i="${i}">${'ABCD'[i]}. ${o}</button>`).join('')}</div><button class="btn primary" id="next">${e.i===19?'Finalizar examen':'Guardar y continuar'}</button></div>`);let s=null;document.querySelectorAll('.opt').forEach(b=>b.onclick=()=>{document.querySelectorAll('.opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');s=+b.dataset.i});$('#next').onclick=()=>{if(s===null)return alert('Selecciona una opción.');e.answers[e.i]=s;if(e.i<19){e.i++;save();examQuestion()}else finishExam()}}
function finishExam(){const e=state.exam;let correct=e.answers.reduce((n,a,i)=>n+(a===exam[i][2]?1:0),0),score=Math.round((1+(correct/20)*4)*10)/10;state.attempts[state.current]??=[];state.attempts[state.current].push({correct,score,answers:e.answers,date:new Date().toISOString()});delete state.exam;save();examResults()}
function examResults(){const ats=state.attempts[state.current]||[],best=ats.length?Math.max(...ats.map(x=>x.score)):null;let html=`<div class="head"><div><span class="eyebrow">RESULTADOS</span><h1>Tu evaluación</h1><p>Revisa tus intentos y la mejor nota.</p></div><div><h2>${best??'—'} / 5.0</h2><small>Mejor nota</small></div></div>`;ats.forEach((a,k)=>{html+=`<section class="panel"><h2>Intento ${k+1}: ${a.score}/5.0 · ${a.correct}/20 correctas</h2>`;a.answers.forEach((ans,i)=>{const q=exam[i],ok=ans===q[2];html+=`<div class="result ${ok?'right':'wrong'}"><b>${i+1}. ${esc(q[0])}</b><p>Tu respuesta: <b>${ans==null?'Sin respuesta':'ABCD'[ans]}</b> · Correcta: <b>${'ABCD'[q[2]]}</b></p><small>${esc(q[3])}</small></div>`});html+='</section>'});if(ats.length<3)html+=`<button class="btn primary" onclick="examIntro()">Presentar otro intento</button>`;shell(html)}
function teacher(){const students=state.users.filter(x=>x.role==='student');let rows='';let totalProg=0,finished=0,exams=0;students.forEach(s=>{const done=Object.values(state.progress[s.email]||{}).filter(x=>x.done).length,pct=done*5,ats=state.attempts[s.email]||[],best=ats.length?Math.max(...ats.map(x=>x.score)):'—';totalProg+=pct;if(done===20)finished++;exams+=ats.length;rows+=`<tr><td><b>${esc(s.first)} ${esc(s.last)}</b><small>${esc(s.code||'')}</small></td><td>${esc(s.inst||'')}</td><td>${esc(s.group||'')}</td><td>${pct}%</td><td>${ats.length}/3</td><td>${best}</td><td><button class="btn small secondary" onclick="teacherStudent('${encodeURIComponent(s.email)}')">Ver</button></td></tr>`});shell(`<span class="eyebrow">PANEL DOCENTE / ADMINISTRADOR</span><h1>Seguimiento del curso</h1><div class="stats"><article><b>${students.length}</b>estudiantes</article><article><b>${students.length?Math.round(totalProg/students.length):0}%</b>progreso promedio</article><article><b>${finished}</b>terminados</article><article><b>${exams}</b>intentos examen</article></div><div class="panel"><div class="head"><h2>Estudiantes</h2><button class="btn secondary" onclick="exportCSV()">Exportar CSV</button></div><div class="tablewrap"><table><thead><tr><th>Estudiante</th><th>Institución</th><th>Grupo</th><th>Progreso</th><th>Intentos</th><th>Mejor nota</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="7">No hay estudiantes registrados.</td></tr>'}</tbody></table></div></div>`)}
function teacherStudent(encoded){const email=decodeURIComponent(encoded),s=state.users.find(x=>x.email===email),p=state.progress[email]||{},ats=state.attempts[email]||[];let h=`<a href="#" onclick="teacher();return false">← Panel docente</a><h1>${esc(s.first)} ${esc(s.last)}</h1><p>${esc(s.inst||'')} · Grupo ${esc(s.group||'')} · Código ${esc(s.code||'')}</p><div class="grid"><section class="panel"><h2>Lecciones</h2>`;lessons.forEach((l,i)=>{const x=p[i+1];h+=`<div class="result"><b>${i+1}. ${l[0]}</b><br><small>${x?.done?'✓ Completada':'No completada'}${x?.completed?' · '+new Date(x.completed).toLocaleString('es-CO'):''}</small></div>`});h+=`</section><section class="panel"><h2>Evaluación</h2>`;ats.forEach((a,i)=>h+=`<div class="result"><b>Intento ${i+1}</b><br>${a.correct}/20 correctas · ${a.score}/5.0<br><small>${new Date(a.date).toLocaleString('es-CO')}</small></div>`);h+='</section></div>';shell(h)}
function exportCSV(){const students=state.users.filter(x=>x.role==='student');let csv='Nombre,Código,Institución,Grupo,Progreso,Intentos,Mejor nota\n';students.forEach(s=>{const done=Object.values(state.progress[s.email]||{}).filter(x=>x.done).length,ats=state.attempts[s.email]||[],best=ats.length?Math.max(...ats.map(x=>x.score)):'';csv+=`"${s.first} ${s.last}","${s.code||''}","${s.inst||''}","${s.group||''}",${done*5},${ats.length},${best}\n`});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='sql11_consolidado.csv';a.click()}
render();
